%[text] **Author: Andreas Apostolatos, PhD (aapostol@mathworks.com)**
%[text] **Date: 20.02.2023**
%%
%[text] %[text:anchor:H_91BCAFD0] ## Preamble
clc;
clear;
close all;
%%
%[text] %[text:anchor:H_5C7001DD] ## **Problem setup**
%[text] %[text:anchor:H_8FFFA9F4] ### Geometric parameters
%[text] %[text:anchor:M_75136542] Thickness \[$m${"editStyle":"visual"}\]
propStr.t = 10^(-1); %[control:slider:8dcb]{"position":[17,19]}
%[text] X-coordinate of the left edge \[$m${"editStyle":"visual"}\]
X0 = 0;
%[text] X-coordinate of the right edge \[$m${"editStyle":"visual"}\]
XLx = 4;
%[text] Y-coordinate of the left edge \[$m${"editStyle":"visual"}\]
Y0 = 0;
%[text] Y-coordinate of the right edge \[$m${"editStyle":"visual"}\]
YLy = 1;
%[text] %[text:anchor:H_52F06E8F] ### Material paramerters
%[text] distributed load \[$N/m^2${"editStyle":"visual"}\]
propStr.pBar = -3e4*(propStr.t)^3;
%[text] distributed moment around x-axis \[$N${"editStyle":"visual"}\]
propStr.mxBar = 0;
%[text] distributed moment around y-axis \[$N${"editStyle":"visual"}\]
propStr.myBar = 0;
%[text] Young's modulus \[$N/m^2${"editStyle":"visual"}\]
propStr.E = 1e7;
%[text] Poisson ration \[dimensionless\]
propStr.nu = 0;
%[text] Shear modulus (connected to `epsilon_12 = E/(1+nu)`) \[$N/m^2${"editStyle":"visual"}\]
propStr.G = propStr.E/2/(1 + propStr.nu);
%[text] Plate stiffness \[$N\\cdot m${"editStyle":"visual"}\]
propStr.D = propStr.E*propStr.t^3/12/(1 - propStr.nu^2);
%[text] Shear correction factor \[dimensionless\]
propStr.alpha = 5/6;
%%
%[text] %[text:anchor:H_701C2D46] ## Derivation of the analytical solution using the Timoshenko beam formulation
%[text] Since the plate is rectangular, clamped on its one end while being subject to constant distributed vertical load its behavior is expected to resemble a beam aligned with the X-axis, whereas no effects are expected to take place along the *`Y`*-axis. The analytical solution for this problem using the shear-deformable Timoshenko beam formulation are in this case as follows
%[text] %[text:anchor:H_A4014F3D] ### Initialize auxiliary variables
syms wEx(X,Y) betaEx(X,Y) Q(X,Y) Lsym psym Gsym Aqsym Esym Isym
%[text] %[text:anchor:H_2E9CC45F] ### Definition of the analytical solution regarding the vertical deflection and rotation field
%[text] Set the analytical solution in terms of the vertical deflection field (Eq. (1) in the introduction):
%[text] $w(X,Y) = \\frac{1}{\\alpha G A} \\left( \\overline{p} L X - \\frac{\\overline{p} X^2}{2} \\right) - \\frac{1}{EI} \\left( - \\frac{\\overline{p} X^4}{24} + \\frac{\\overline{p} L X^3}{6} - \\frac{\\overline{p} L^2 X^2}{4} \\right)$
%[text] namely:
wEx(X,Y) = (psym*Lsym*X-psym*X^2/2)/Gsym/(Aqsym) - ...
    (-psym*X^4/24+psym*Lsym*X^3/6-psym*Lsym^2*X^2/4)/Esym/Isym;
%[text] Get the analytical solution of the rotational field by leveraging the Partial Differential Equation (PDE) of the problem and the functions of the [Symbolic Math Toolbox](https://www.mathworks.com/products/symbolic.html) in [MATLAB](https://www.mathworks.com/products/matlab.html)
%[text] $\\beta(X) = \\int\_{0}^L - \\frac{1}{\\alpha G A}\\overline{p} - \\frac{\\text{d}^2 w}{\\text{d} x^2} \\: \\text{d}x$
betaEx(X,Y) = int(-1/(propStr.alpha*propStr.G*YLy*propStr.t)*...
    propStr.pBar - diff(diff(wEx, X), X));
%[text] %[text:anchor:H_65E9C54B] ### Substitution of the known parameters in the analytical expression
wEx(X,Y) = subs(wEx,{Lsym, psym, Gsym, Esym, Isym, Aqsym}, ...
    {XLx, propStr.pBar, propStr.G, propStr.E, YLy*(propStr.t^3)/12, ...
    propStr.alpha*YLy*propStr.t});
betaEx(X,Y) = subs(betaEx,{Lsym, psym, Gsym, Esym, Isym, Aqsym}, ...
    {XLx, propStr.pBar, propStr.G, propStr.E, YLy*(propStr.t^3)/12, ...
    propStr.alpha*YLy*propStr.t});
Q(X,Y) = propStr.alpha*YLy*propStr.t*propStr.G*(betaEx(X,Y) + ...
    diff(wEx, X));
%%
%[text] %[text:anchor:H_5092B7FF] ## **Basis functions**
%[text] %[text:anchor:H_25FA2CE5] ### **Bilinear basis functions**
%[text] $N\_1^{Q\_1}(\\xi, \\eta) = \\frac{1}{4}(1 - \\xi)(1 - \\eta) \\quad (\\xi,\\eta) \\in \[-1, 1\]^2, \\quad (8.1) \\\\\nN\_2^{Q\_1}(\\xi, \\eta) = \\frac{1}{4}(1 + \\xi)(1 - \\eta) \\quad (\\xi,\\eta) \\in \[-1, 1\]^2, \\quad (8.2) \\\\\nN\_3^{Q\_1}(\\xi, \\eta) = \\frac{1}{4}(1 + \\xi)(1 + \\eta) \\quad (\\xi,\\eta) \\in \[-1, 1\],^2 \\quad (8.3)\\\\\nN\_4^{Q\_1}(\\xi, \\eta) = \\frac{1}{4}(1 - \\xi)(1 + \\eta) \\quad (\\xi,\\eta) \\in \[-1, 1\]^2. \\quad (8.4)$ 
%[text] %[text:anchor:H_14C6D896] #### Definition
syms N1Q1(xi, eta) N2Q1(xi, eta) N3Q1(xi, eta) N4Q1(xi, eta)
N1Q1(xi, eta) = (1 - xi)*(1 - eta)/4;
N2Q1(xi, eta) = (1 + xi)*(1 - eta)/4;
N3Q1(xi, eta) = (1 + xi)*(1 + eta)/4;
N4Q1(xi, eta) = (1 - xi)*(1 + eta)/4;
NQ1 = {N1Q1 N4Q1 N3Q1 N2Q1};
%[text] %[text:anchor:H_89FF6DAE] #### Visual representation
figure, %[output:39e94928]
t1 = tiledlayout(2, 2); %[output:39e94928]
title(t1, "Bilinear shape functions") %[output:39e94928]
for ii = 1:numel(NQ1) %[output:group:039d0d52]
    nexttile %[output:39e94928]
    fsurf(NQ1{ii}, [-1 1 -1 1], LineStyle='-', ...
        FaceColor=[217 218 219]/255, FaceAlpha=3/4);
    xlabel("\xi");
    ylabel("\eta");
    zlabel(strcat(sprintf("N_%i", ii),"(\xi, \eta)"));
end %[output:group:039d0d52]
%[text] %[text:anchor:H_61253FCE] ### **Biquadratic basis Functions**
%[text] $N\_1^{Q\_2}(\\xi, \\eta) = \\frac{1}{4} \\xi (\\xi - 1) \\eta (1 - \\eta) \\quad (\\xi,\\eta) \\in \[0, 1\], \\quad \\quad \\quad \\, \\quad(9.1) \\\\\nN\_2^{Q\_2}(\\xi, \\eta) = -\\frac{1}{2}(\\xi + 1)(\\xi - 1)\\eta(\\eta - 1) \\quad (\\xi,\\eta) \\in \[0, 1\], \\quad(9.2) \\\\\nN\_3^{Q\_2}(\\xi, \\eta) = \\frac{1}{4}(\\xi + 1)\\xi \\eta(\\eta - 1) \\quad (\\xi,\\eta) \\in \[0, 1\],  \\quad \\quad \\quad \\, \\quad(9.3) \\\\\nN\_4^{Q\_2}(\\xi, \\eta) = -\\frac{1}{2}(\\xi + 1)\\xi(\\eta + 1)(\\eta - 1) \\quad (\\xi,\\eta) \\in \[0, 1\], \\quad(9.4) \\\\\nN\_5^{Q\_2}(\\xi, \\eta) = \\frac{1}{4}(\\xi + 1)\\xi(\\eta + 1)\\eta \\quad (\\xi,\\eta) \\in \[0, 1\],  \\quad \\quad \\quad \\, \\quad(9.5) \\\\\nN\_6^{Q\_2}(\\xi, \\eta) = -\\frac{1}{2}(\\xi + 1)(\\xi - 1)(\\eta + 1)\\eta \\quad (\\xi,\\eta) \\in \[0, 1\], \\quad(9.6) \\\\\nN\_7^{Q\_2}(\\xi, \\eta) = \\frac{1}{4}\\xi (\\xi - 1)(\\eta + 1)\\eta \\quad (\\xi,\\eta) \\in \[0, 1\], \\quad \\quad \\quad \\, \\quad(9.7) \\\\\nN\_8^{Q\_2}(\\xi, \\eta) = -\\frac{1}{2}\\xi (\\xi - 1)(\\eta + 1)(\\eta - 1) \\quad (\\xi,\\eta) \\in \[0, 1\], \\quad(9.8) \\\\\nN\_9^{Q\_2}(\\xi, \\eta) = \\frac{1}{1}(1 - \\xi^2) (1 - \\eta^2)\\quad (\\xi,\\eta) \\in \[0, 1\]. \\quad \\quad \\quad \\; \\, \\quad(9.9)$
%[text] %[text:anchor:H_BCA8FAD2] #### **Definition**
syms N1Q2(xi, eta) N2Q2(xi, eta) N3Q2(xi, eta) N4Q2(xi, eta) ...
    N5Q2(xi, eta) N6Q2(xi, eta) N7Q2(xi, eta) N8Q2(xi, eta) ...
    N9Q2(xi, eta)
N1Q2(xi, eta) = xi*(xi - 1)*eta*(eta - 1)/4;
N2Q2(xi, eta) = (xi + 1)*(xi - 1)*eta*(eta - 1)/-2;
N3Q2(xi, eta) = (xi + 1)*xi*eta*(eta - 1)/4;
N4Q2(xi, eta) = (xi + 1)*xi*(eta + 1)*(eta - 1)/-2;
N5Q2(xi, eta) = (xi + 1)*xi*(eta + 1)*eta/4;
N6Q2(xi, eta) = (xi + 1)*(xi - 1)*(eta + 1)*eta/-2;
N7Q2(xi, eta) = xi*(xi - 1)*(eta + 1)*eta/4;
N8Q2(xi, eta) = xi*(xi - 1)*(eta + 1)*(eta - 1)/-2;
N9Q2(xi, eta) = (xi + 1)*(xi - 1)*(eta + 1)*(eta - 1)/1;
NQ2 = {N1Q2 N7Q2 N5Q2 N3Q2 N8Q2 N4Q2 N2Q2 N6Q2 N9Q2};
%[text] %[text:anchor:H_450BA31A] #### Visual representation
figure, %[output:6def7db6]
t1 = tiledlayout(3, 3); %[output:6def7db6]
title(t1, "Biquadratic shape functions") %[output:6def7db6]
for ii = 1:numel(NQ2) %[output:group:94c61ea3]
    nexttile %[output:6def7db6]
    fsurf(NQ2{ii}, [-1 1 -1 1], LineStyle='-', ...
        FaceColor=[217 218 219]/255, FaceAlpha=3/4);
    xlabel("\xi");
    ylabel("\eta");
    zlabel(strcat(sprintf("N_%i", ii),"(\xi, \eta)"));
end %[output:group:94c61ea3]
%[text] %[text:anchor:H_C6E04EA7] ### **Linear triangular basis functions**
%[text] $N\_1^{T\_1}(\\xi, \\eta) = \\xi \\quad (\\xi,\\eta) \\in \[-1, 1\]^2 \\text{ with } \\xi + \\eta \\le 1, \\quad \\quad \\quad \\quad (10.1) \\\\\nN\_2^{T\_1}(\\xi, \\eta) = \\eta \\quad (\\xi,\\eta) \\in \[-1, 1\]^2 \\text{ with } \\xi + \\eta \\le 1, \\quad \\quad \\quad \\quad (10.2) \\\\\nN\_3^{T\_1}(\\xi, \\eta) = 1 - \\xi - \\eta \\quad (\\xi , \\eta) \\in \[-1, 1\]^2 \\text{ with } \\xi + \\eta \\le 1 \\quad (10.3)$ 
%[text] %[text:anchor:H_BEC07434] #### Definition
syms N1T1(xi, eta) N2T1(xi, eta) N3T1(xi, eta)
N1T1(xi, eta) = xi;
N2T1(xi, eta) = eta;
N3T1(xi, eta) = 1 - xi- eta;
NT1 = {N1T1 N2T1 N3T1};
%%
%[text] %[text:anchor:H_0361188C] ## **Basis functions derivatives**
%[text] $N\_{i,\\xi}(\\xi,\\eta) = \\frac{\\partial N\_i^{Q\_1}(\\xi,\\eta)}{\\partial \\xi}, \\quad (11.1) \\\\\nN\_{i,\\eta}(\\xi,\\eta) = \\frac{\\partial N\_i^{Q\_1}(\\xi,\\eta)}{\\partial \\eta}. \\quad (11.2)$
%[text] %[text:anchor:H_F615DDD7] ### **Parametric derivatives of the bilinear basis functions**
figure, %[output:4c8cd501]
t2 = tiledlayout(4, 2); %[output:4c8cd501]
paramSpace = [xi eta];
paramSpaceStr = {'\xi', '\eta'};
title(t2, "Derivatives of the bilinear shape functions") %[output:4c8cd501]
for ii = 1:numel(NQ1) %[output:group:1accb637]
    for jj = 1:2
        nexttile %[output:4c8cd501]
        fsurf(diff(NQ1{ii}, paramSpace(jj)), [-1 1 -1 1], ...
            LineStyle='-', FaceColor=[217 218 219]/255, FaceAlpha=3/4);
        xlabel("\xi");
        ylabel("\eta");
        zlabel(sprintf("^{\\partial N_{%d} (\\xi, \\eta)}/_{\\partial%s}", ...
            ii, paramSpaceStr{jj}));
    end
end %[output:group:1accb637]
%[text] %[text:anchor:H_D2AB2865] ### **Derivation of the parametric derivatives of the biquadratic basis functions**
figure, %[output:61d8c9c1]
t2 = tiledlayout(9, 2); %[output:61d8c9c1]
paramSpace = [xi eta];
paramSpaceStr = {'\xi', '\eta'};
title(t2, "Derivatives of the bilinear shape functions") %[output:61d8c9c1]
for ii = 1:numel(NQ2) %[output:group:2e1d82e9]
    for jj = 1:2
        nexttile %[output:61d8c9c1]
        fsurf(diff(NQ2{ii}, paramSpace(jj)), [-1 1 -1 1], LineStyle='-', ...
            FaceColor=[217 218 219]/255, FaceAlpha=3/4);
        xlabel("\xi");
        ylabel("\eta");
        zlabel(sprintf("^{\\partial N_{%d} (\\xi, \\eta)}/_{\\partial%s}", ...
            ii, paramSpaceStr{jj}));
    end
end %[output:group:2e1d82e9]
%%
%[text] %[text:anchor:H_76F0D5D7] ## **Discretization**
%[text] Both the vertical deflection $w$ and cross-sectional rotation $\\beta\_x$, $\\beta\_y$ fields are discretized using the same basis (shape) functions, namely:
%[text] $\\begin{array}{l}\nw\\left(\\xi ,\\eta \\right)\\approx \\sum\_{i=1:N} N\_i \\left(\\xi ,\\eta \\right)\\;w\_i ,\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(12\\ldotp 1\\right)\\\\\n\\beta\_x \\left(\\xi ,\\eta \\right)\\approx \\sum\_{i=1:N} N\_i \\left(\\xi ,\\eta \\right)\\;\\beta\_{x,i} \\;\\ldotp \\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(12\\ldotp 2\\right)\\\\\n\\beta\_y \\left(\\xi ,\\eta \\right)\\approx \\sum\_{i=1:N} N\_i \\left(\\xi ,\\eta \\right)\\;\\beta\_{y,i} \\;\\ldotp \\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(12\\ldotp 3\\right)\n\\end{array}${"editStyle":"visual"}
%[text] Here $N$ indicates the total number of nodes in the mesh. Moreover a Buvnov-Galerkin discretization is used, meaning that both the test and the unknown fields are discretized using the same basis (shape) functions.
%%
%[text] %[text:anchor:H_E80594AC] ### Quadrilateral mesh
%[text] %[text:anchor:H_BCC3B8B6] #### Choose number of elements in the mesh
%[text] %[text:anchor:M_CCACD04E] Number of elements along the *`X`*-direction
numElx = 7; % 7 %[control:slider:5e1c]{"position":[10,11]} %[text:anchor:M_9405611F]
%[text] Number of elements along the Y-direction
numEly = 2; % 2 %[control:slider:7f6d]{"position":[10,11]} %[text:anchor:M_A24539F5]
%[text] ![](text:image:33b4) **Try**
%[text] Change the number of elements along the $X$- and $Y$-Cartesian direction using the numeric slider for variable [`numElx`](internal:M_9405611F) and [`numEly`](internal:M_A24539F5), respectively.
%[text] ![](text:image:13a6) **Reflect**
%[text] What can you say about the solution of the bilinear quadrilateral and linear triangular elements as compared to the biquadratic quadrilateral elements?
%%
%[text] %[text:anchor:H_5A9A09EB] #### Mesh generation
numEl = numElx*numEly;
[nodesX, nodesY] = generateQuadrilateralMesh ...
    (X0, XLx, Y0, YLy, numElx, numEly);
%%
%[text] %[text:anchor:H_23BD88B7] ### **Four-noded bilinear quadrilateral mesh**
%[text] %[text:anchor:H_7648C8D4] #### **Mesh generation**
numNodesElQ1 = 4;
mshQ1 = generateBilinearQuadrilateralMesh ...
    (numElx, numEly, numEl, nodesX, nodesY, numNodesElQ1);
numNodesQ1 = numel(mshQ1.nodes(:, 1));
%[text] %[text:anchor:H_296435E6] #### Rendering the mesh non-uniform
isMeshNonUniform = false; %[control:checkbox:3310]{"position":[20,25]} %[text:anchor:M_86560902]
if isMeshNonUniform % Move the nodes of the mesh randomly
    for ii = 1:numNodesQ1
        mshQ1.nodes(ii, 1:2) = mshQ1.nodes(ii, 1:2) + rand(1,2)/5;
    end
    nodesX = reshape(mshQ1.nodes(:, 1), height(nodesX), []);
    nodesY = mshQ1.nodes(:, 2);
end
%[text] %[text:anchor:H_23D38D20] #### Dirichlet boundary conditions for the mesh with the bilinear quadrilateral elements
numDOFsQ1 = 3*numNodesQ1;
[freeDOFsQ1, homDOFsQ1] = ...
    utilityFunctionsCantileverPlate.getFreeDOFsBilinearQuadrilateralMesh ...
    (numNodesQ1, numEly);
numVertices = numel(mshQ1.nodes(:, 1));
%[text] %[text:anchor:H_660CB86F] #### Mesh plot
figure, %[output:96adabba]
plotMesh2d(mshQ1, numVertices, true); %[output:96adabba]
hold on; %[output:96adabba]
scalVer = 1;
[xsQ1, ysQ1, zsQ1] = createSupports3D(mshQ1.nodes, homDOFsQ1, scalVer);
for k = 1:length(xsQ1(:, 1))
    plot3(xsQ1(k, :), ysQ1(k, :), zsQ1(k, :), 'Linewidth', 2, ... %[output:96adabba]
        'Color', 'black'); %[output:96adabba]
end
hold off; %[output:96adabba]
axis equal; %[output:96adabba]
xlabel("x") %[output:96adabba]
ylabel("y") %[output:96adabba]
zlabel("z") %[output:96adabba]
%[text] %[text:anchor:H_D92AFA35] #### Display the mesh with the basis functions
