%%
%[text] %[text:anchor:H_ED60E4F1] ## References
%[text] [\[1\] Hughes, Thomas JR. *The finite element method: linear static and dynamic finite element analysis*. Courier Corporation, 2012.](https://doi.org/10.1111/j.1467-8667.1989.tb00025.x)
%[text] [](https://doi.org/10.1007/978-3-540-78319-0)[\[2\] Brezzi, F., Boffi, D., Demkowicz, L., Durán, R. G., Falk, R. S., & Fortin, M. (2008). Mixed finite elements, compatibility conditions, and applications. *Springer*, *2*, 4-2.](https://doi.org/10.1007/978-3-540-78319-0)
%[text] [\[3\] Holzer, Stefan, Ernst Rank, and Heinrich Werner. "An implementation of the hp‐version of the finite element method for Reissner‐Mindlin plate problems." *International Journal for Numerical Methods in Engineering* 30.3 (1990): 459-471.](https://onlinelibrary.wiley.com/doi/abs/10.1002/nme.1620300306)
%%
%[text] %[text:anchor:H_A1C4FBEC] ## **Helper functions**
%[text] %[text:anchor:H_E22123DD] ### **Element Stiffness Matrix and body force vector for quadrilateral elements**
function [Ke, Fe] = ...
    computeElementStiffMatrixandForceVectorReissnerMindlinPlate ...
    (X, N, propStr)
%[text] %[text:anchor:H_F4F26E8F] **Function description**
%[text] Computation of the element stiffness matrix for an element based on the 2D Reissner-Mindlin plate theory with three degrees of freedom per node $\\left(w,\\beta\_x ,\\beta\_y \\right)${"editStyle":"visual"}, the vertical deflection and two rotations of the plate's cross section around the X- and the Y-axis, respectively.
%[text] 
%[text] %[text:anchor:H_34EA5EE8]  **Input :**
%[text]  `X` : Array containing the nodal coordinates of the nodes in the element
%[text]  `N` : Cell array containing the symbolic expression for the basis functions
%[text]  `propStr` : MATLAB-struct containing the following fields,
%[text]  `.t` : Thickness of the shell
%[text]  `.q` : Distributed load on the shell
%[text]  `.mxBar` : Distributed moment on the beam around x-axis
%[text]  `.myBar` : Distributed moment on the beam around y-axis
%[text]  `.E` : Young's modulus
%[text]  `.nu` : Poisson's ratio
%[text]  `.G` : Shear modulus
%[text]  `.D` : Plate's stiffness
%[text]  `.alpha` : Shear correction factor
%[text] %[text:anchor:H_E05E31E9]  **Output :**
%[text]  `Ke` : Element stiffness matrix of a Reissner-Mindlin shell
%[text]  `Fe` : Element force vector of a Reissner-Mindlin shell
%[text] %[text:anchor:H_88F173D4] **Function implementation**
%[text] Input validation
    arguments
        X (:, 2) double {mustBeReal}
        N (1, :) cell
        propStr (1, 1) struct {mustHaveReissnerMindlinPlateProperties}
    end
%[text] Read input
    syms xi eta
    numNodesEl = height(X);
    numDOFsEl = 3*numNodesEl;
    if numel(X(:, 1)) ~= numel(N)
        error("Numner of nodes does not match the number of basis functions");
    end
    if numNodesEl == 4 || numNodesEl == 9
        isQuadMesh = true;
    elseif numNodesEl == 3 || numNodesEl == 7
        isQuadMesh = false;
    else
        error("Visualization for a mesh with elements that have %d " + ...
            "number of nodes is not implemented", numNodes_el);
    end
%[text] Computation of the material matrix
    C = [propStr.alpha*propStr.G*propStr.t 0                                 0                    0                     0
         0                                 propStr.alpha*propStr.G*propStr.t 0                    0                     0
         0                                 0                                 propStr.D            propStr.nu*propStr.D  0
         0                                 0                                 propStr.nu*propStr.D propStr.D             0
         0                                 0                                 0                    0                     propStr.D/2*(1 - propStr.nu)];
%[text] Formulation of the basis function's matrix
    Nmtx = sym(zeros(3, numDOFsEl));
    for ii = 1:numNodesEl
        Nmtx(1, 3*ii - 2) = N{ii};
        Nmtx(2, 3*ii - 1) = N{ii};
        Nmtx(3, 3*ii) = N{ii};
    end
%[text] Formulation of the geometry map
    pos_vct(xi, eta) = transpose([N{:}]*X(:, 1:2));
%[text] Formulate the Jacobian matrix
    Jacobian_mtx(xi, eta) = jacobian(pos_vct, [xi eta]);
%[text] Compute the determinant of the Jacobian
    detJ(xi, eta) = simplify(det(Jacobian_mtx(xi, eta)));
%[text] Compute the derivatives of the basis functions with respect to the physical space in the parametric space
    dNdXY(xi, eta) = simplify(transpose(transpose(Jacobian_mtx(xi, eta)) ...
        \[diff([N{:}], xi); diff([N{:}], eta)]));
%[text] Formulate the B-operator matrix for the Reissner-Mindlin plate
    Bmtx = sym(zeros(5, numDOFsEl));
    for ii = 1:numNodesEl
        idx_vct_bf = zeros(1, numel(N));
        idx_vct_bf(1, ii) = 1;
        Bmtx(1, 3*ii - 2) = idx_vct_bf*dNdXY*[1; 0];
        Bmtx(1, 3*ii) = N{ii};
        Bmtx(2, 3*ii - 2) = idx_vct_bf*dNdXY*[0; 1];
        Bmtx(2, 3*ii - 1) = -N{ii};
        Bmtx(3, 3*ii) = idx_vct_bf*dNdXY*[1; 0];
        Bmtx(4, 3*ii - 1) = -idx_vct_bf*dNdXY*[0; 1];
        Bmtx(5, 3*ii - 1) = -idx_vct_bf*dNdXY*[1; 0];
        Bmtx(5, 3*ii) = idx_vct_bf*dNdXY*[0; 1];
    end
%[text] Formulate the integrand of the stiffness matrix and the body load vector for the Reissner-Mindlin plate
    KeInt(xi, eta) = transpose(Bmtx)*C*Bmtx*detJ;
    FeInt(xi, eta) = transpose(Nmtx)*...
        [propStr.pBar; propStr.mxBar; propStr.myBar]*detJ;
%[text] Compute the stiffness matrix for the Reissner-Mindlin plate
%     Ke = int(int(Ke_integrand, eta, -1, 1), xi, -1, 1);
    Ke = zeros(numDOFsEl);
    if isQuadMesh
        [xiGP, GWXi] = getGaussPointsAndWeightsOverUnitDomain(2);
        [etaGP, GWEta] = getGaussPointsAndWeightsOverUnitDomain(2);
        for jj = 1:height(GWEta)
            for ii = 1:height(GWXi)
                Ke = Ke + KeInt(xiGP(ii), etaGP(jj))*GWXi(ii)*GWEta(jj);
            end
        end
    else
        [GP, GW] = getGaussPointsAndWeightsOnCanonicalTriangle(2);
        numGP = height(GP);
        for ii = 1:numGP
            Ke = Ke + KeInt(GP(2, ii), GP(3, ii))*GW(ii);
        end
    end
%[text] Compute the body load vector for the Reissner-Mindlin plate
%     Fe = int(int(Fe_integrand, eta, -1, 1), xi, -1, 1);
    Fe = zeros(numDOFsEl, 1);
    if isQuadMesh
        [xiGP, GWXi] = getGaussPointsAndWeightsOverUnitDomain(2);
        [etaGP, GWEta] = getGaussPointsAndWeightsOverUnitDomain(2);
        for jj = 1:height(GWEta)
            for ii = 1:height(GWXi)
                Fe = Fe + FeInt(xiGP(ii), etaGP(jj))*GWXi(ii)*GWEta(jj);
            end
        end
    else
        [GP, GW] = getGaussPointsAndWeightsOnCanonicalTriangle(2);
        numGP = height(GP);
        for ii = 1:numGP
            Fe = Fe + FeInt(GP(2, ii), GP(3, ii))*GW(ii);
        end
    end
%[text] Compute the stiffness matrix and body load vector with double precision
    Ke = double(Ke);
    Fe = double(Fe);
%[text] 
end

